local Control=require(script.Parent.Parent.Base.Control)
return function(ctx,text,min,max,default,callback,step) min=min or 0;max=max or 100;default=math.clamp(default or min,min,max);local f=Instance.new("Frame",ctx.Parent);f.Name="Slider";f.Size=UDim2.new(1,0,0,54);f.BackgroundTransparency=1;local lab=Instance.new("TextLabel",f);lab.BackgroundTransparency=1;lab.Size=UDim2.new(1,-64,0,20);lab.Text=text or "Slider";lab.TextColor3=ctx.Theme:Get("Text");lab.Font=Enum.Font.Gotham;lab.TextSize=14;lab.TextXAlignment=Enum.TextXAlignment.Left;local value=Instance.new("TextLabel",f);value.BackgroundTransparency=1;value.Position=UDim2.new(1,-58,0,0);value.Size=UDim2.fromOffset(58,20);value.TextColor3=ctx.Theme:Get("Muted");value.Font=Enum.Font.Gotham;value.TextSize=12;local track=Instance.new("TextButton",f);track.Position=UDim2.fromOffset(0,30);track.Size=UDim2.new(1,0,0,8);track.BackgroundColor3=ctx.Theme:Get("Border");track.Text="";Instance.new("UICorner",track).CornerRadius=UDim.new(1,0);local fill=Instance.new("Frame",track);fill.BackgroundColor3=ctx.Theme:Get("Accent");fill.Size=UDim2.new(0,0,1,0);Instance.new("UICorner",fill).CornerRadius=UDim.new(1,0);local knob=Instance.new("Frame",track);knob.Size=UDim2.fromOffset(18,18);knob.AnchorPoint=Vector2.new(.5,.5);knob.Position=UDim2.new(0,0,.5,0);knob.BackgroundColor3=Color3.new(1,1,1);Instance.new("UICorner",knob).CornerRadius=UDim.new(1,0);local c=Control.new(f,ctx,default);local function set(v,silent) v=math.clamp(v,min,max);if step then v=math.floor(v/step+0.5)*step end;local t=(v-min)/(max-min);fill.Size=UDim2.new(t,0,1,0);knob.Position=UDim2.new(t,0,.5,0);value.Text=tostring(v);c:SetValue(v,silent)end;set(default,true);local dragging=false;ctx.Maid:Give(track.InputBegan:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 or i.UserInputType==Enum.UserInputType.Touch then dragging=true;set(min+(max-min)*((i.Position.X-track.AbsolutePosition.X)/track.AbsoluteSize.X))end end));ctx.Maid:Give(game:GetService("UserInputService").InputChanged:Connect(function(i